    @java.lang.Override
    public boolean equals(Object other) {
        if (this == other) return true;
        return other instanceof Ad && equalTo((Ad) other);
    }

    @JsonAnyGetter
    public Map<String, Object> getAdditionalProperties() {
        return this.additionalProperties;
    }

    private boolean equalTo(Ad other) {
        return adCampaign.equals(other.adCampaign)
                && adGroup.equals(other.adGroup)
                && addedToCartValue == other.addedToCartValue
                && addedToCarts == other.addedToCarts
                && callToAction.equals(other.callToAction)
                && clickThroughRate == other.clickThroughRate
                && clicks == other.clicks
                && completedRegistrationValue == other.completedRegistrationValue
                && completedRegistrations == other.completedRegistrations
                && contactValue == other.contactValue
                && contacts == other.contacts
                && costPerAddedToCart.equals(other.costPerAddedToCart)
                && costPerClick == other.costPerClick
                && costPerCompletedRegistration.equals(other.costPerCompletedRegistration)
                && costPerContact.equals(other.costPerContact)
                && costPerLead.equals(other.costPerLead)
                && costPerMille == other.costPerMille
                && costPerPurchase.equals(other.costPerPurchase)
                && costPerResult.equals(other.costPerResult)
                && costPerSchedule.equals(other.costPerSchedule)
                && costPerSubmittedApplication.equals(other.costPerSubmittedApplication)
                && costPerUniqueClick.equals(other.costPerUniqueClick)
                && costPerViewedContent.equals(other.costPerViewedContent)
                && createdAt.equals(other.createdAt)
                && creatives.equals(other.creatives)
                && customConversions == other.customConversions
                && customEventCounts.equals(other.customEventCounts)
                && customEventValues.equals(other.customEventValues)
                && deliveryStatus.equals(other.deliveryStatus)
                && descriptions.equals(other.descriptions)
                && frequency.equals(other.frequency)
                && headlines.equals(other.headlines)
                && id.equals(other.id)
                && impressions == other.impressions
                && issues.equals(other.issues)
                && leadForm.equals(other.leadForm)
                && leadFormId.equals(other.leadFormId)
                && leadValue == other.leadValue
                && leads == other.leads
                && messagingConfig.equals(other.messagingConfig)
                && multiAdvertiserAds.equals(other.multiAdvertiserAds)
                && postId.equals(other.postId)
                && postSource.equals(other.postSource)
                && postThumbnailUrl.equals(other.postThumbnailUrl)
                && primaryTexts.equals(other.primaryTexts)
                && purchaseValue == other.purchaseValue
                && purchases == other.purchases
                && reach == other.reach
                && resultEvent.equals(other.resultEvent)
                && resultEventName.equals(other.resultEventName)
                && results.equals(other.results)
                && returnOnAdSpend == other.returnOnAdSpend
                && scheduleValue == other.scheduleValue
                && schedules == other.schedules
                && socialAccounts.equals(other.socialAccounts)
                && spend == other.spend
                && spendCurrency.equals(other.spendCurrency)
                && status.equals(other.status)
                && submittedApplicationValue == other.submittedApplicationValue
                && submittedApplications == other.submittedApplications
                && title.equals(other.title)
                && uniqueClickThroughRate.equals(other.uniqueClickThroughRate)
                && uniqueClicks == other.uniqueClicks
                && updatedAt.equals(other.updatedAt)
                && url.equals(other.url)
                && urlParameters.equals(other.urlParameters)
                && viewedContentValue == other.viewedContentValue
                && viewedContents == other.viewedContents;
    }

